# region: render
def render(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: intake
def intake(xs, offset=4):
    return [v + offset for v in xs]

# region: emit
def emit(xs, offset=4):
    return [v + offset for v in xs]

# region: sift
def sift(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': min(xs) if xs else 0}

# region: shape
def shape(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return shape(sift(emit(intake(render(raw)))))

